import torch
from torch import Tensor

c = 1.0

def u(t: Tensor, x: Tensor, y: Tensor, z: Tensor) -> Tensor:
	E_x = torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)*x*z*(3+300.0*t*x**2-45.0*(x**2+y**2+z**2)**(1/2)-300.0*(x**2+y**2+z**2)**(1/2)*x**2-300.0*(x**2+y**2+z**2)**(1/2)*y**2-300.0*z**2*(x**2+y**2+z**2)**(1/2)-30*(x**2+y**2+z**2)**(1/2)*t+200*x**2*y**2+200*x**2*z**2+200*y**2*z**2-200*(x**2+y**2+z**2)**(1/2)*t*x**2-200*(x**2+y**2+z**2)**(1/2)*t*y**2-200*z**2*(x**2+y**2+z**2)**(1/2)*t+100*x**4+100*y**4+100*z**4+245.00*x**2+245.00*y**2+245.00*z**2+100*t**2*x**2+100*t**2*y**2+100*t**2*z**2+300.0*t*y**2+300.0*t*z**2)/(x**2+y**2+z**2)**(5/2)
	E_y =  torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)*y*z*(3+300.0*t*x**2-45.0*(x**2+y**2+z**2)**(1/2)-300.0*(x**2+y**2+z**2)**(1/2)*x**2-300.0*(x**2+y**2+z**2)**(1/2)*y**2-300.0*z**2*(x**2+y**2+z**2)**(1/2)-30*(x**2+y**2+z**2)**(1/2)*t+200*x**2*y**2+200*x**2*z**2+200*y**2*z**2-200*(x**2+y**2+z**2)**(1/2)*t*x**2-200*(x**2+y**2+z**2)**(1/2)*t*y**2-200*z**2*(x**2+y**2+z**2)**(1/2)*t+100*x**4+100*y**4+100*z**4+245.00*x**2+245.00*y**2+245.00*z**2+100*t**2*x**2+100*t**2*y**2+100*t**2*z**2+300.0*t*y**2+300.0*t*z**2)/(x**2+y**2+z**2)**(5/2)
	E_z =  -100.0000000*(((-2.000000000*t-3.000000000)*x**4+((-6.000000000-4.000000000*t)*y**2+(-2.000000000*t-3.000000000)*z**2-.1000000000*t-.1500000000)*x**2+(-2.000000000*t-3.000000000)*y**4+((-2.000000000*t-3.000000000)*z**2-.1000000000*t-.1500000000)*y**2+(.2000000000*t+.3000000000)*z**2)*(x**2+y**2+z**2)**(1/2)+1.000000000*x**6+(3.000000000*y**2+2.000000000*z**2+(t+1.500000000)**2)*x**4+(3.000000000*y**4+(4.000000000*z**2+2.000000000*(t+1.500000000)**2)*y**2+.1000000000e-1+1.000000000*z**4+(t+1.947213595)*(t+1.052786405)*z**2)*x**2+1.000000000*y**6+(2.000000000*z**2+(t+1.500000000)**2)*y**4+(.1000000000e-1+1.000000000*z**4+(t+1.947213595)*(t+1.052786405)*z**2)*y**2-.2000000000e-1*z**2-.2000000000*z**4)*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)/(x**2+y**2+z**2)**(5/2)
	B_x =  -5.*(20.*(x**2+y**2+z**2)**(1/2)*t**2+20.*(x**2+y**2+z**2)**(1/2)*x**2+20.*(x**2+y**2+z**2)**(1/2)*y**2+20.*z**2*(x**2+y**2+z**2)**(1/2)-40.*t*x**2-40.*t*y**2-40.*t*z**2+60.*(x**2+y**2+z**2)**(1/2)*t-60.*x**2-60.*y**2-60.*z**2+45.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)*y*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)/(x**2+y**2+z**2)**(3/2)
	B_y =  5.*(20.*(x**2+y**2+z**2)**(1/2)*t**2+20.*(x**2+y**2+z**2)**(1/2)*x**2+20.*(x**2+y**2+z**2)**(1/2)*y**2+20.*z**2*(x**2+y**2+z**2)**(1/2)-40.*t*x**2-40.*t*y**2-40.*t*z**2+60.*(x**2+y**2+z**2)**(1/2)*t-60.*x**2-60.*y**2-60.*z**2+45.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)*x*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)/(x**2+y**2+z**2)**(3/2)
	B_z = torch.zeros(t.size()).to(t.device)

	return torch.vstack((E_x, E_y, E_z, B_x, B_y, B_z))